<?php use App\Core\Security;$baseUrl=rtrim((require BASE_PATH.'/config/app.php')['url'],'/');$escape=static fn(mixed $v):string=>Security::escape((string)$v);$replies=is_array($replies??null)?$replies:[];$message=$message??null;?>
<section class="dashboard-page"><div class="dashboard-topbar"><button class="dashboard-menu-toggle" type="button" data-dashboard-toggle aria-expanded="false" aria-controls="dashboard-sidebar" aria-label="Open dashboard menu"><span></span><span></span><span></span></button><div class="dashboard-breadcrumb"><a href="<?=$escape($baseUrl)?>/dashboard">Workspace</a><i>/</i><a href="<?=$escape($baseUrl)?>/notifications">Notifications</a><i>/</i><strong>Conversation</strong></div></div><header class="dashboard-heading"><div><p class="eyebrow">PRIVATE CONVERSATION</p><h1><?=$escape($notification['title'])?></h1><p>Published <?=$escape(date('M j, Y H:i',strtotime($notification['published_at'])))?> by <?=$escape($notification['author_name'])?></p></div></header><?php if($message):?><div class="admin-alert admin-alert-success" role="status"><?=$escape($message)?></div><?php endif;?>
<section class="dashboard-panel notification-thread"><article class="notification-message"><p class="eyebrow">ACADEMY ANNOUNCEMENT</p><div><?=nl2br($escape($notification['body']))?></div></article>
<?php if($user['role']==='admin'):?><form method="get" action="<?=$escape($baseUrl)?>/notifications/view" class="notification-recipient-select"><input type="hidden" name="notification_id" value="<?=(int)$notification['id']?>"><label class="admin-label">Private reply thread<select class="admin-select" name="student_id" required><option value="">Select a recipient</option><?php foreach(($recipients??[]) as $item):?><option value="<?=(int)$item['id']?>" <?=(int)($recipient['id']??0)===(int)$item['id']?'selected':''?>><?=$escape($item['full_name'])?> · <?=$escape($item['email'])?></option><?php endforeach;?></select></label><button class="button button-secondary" type="submit">Open thread</button></form><?php endif;?>
<?php foreach($replies as $reply):?><article class="notification-message notification-reply"><p class="eyebrow"><?=$escape($reply['author_name'])?> · <?=$reply['author_role']==='admin'?'ACADEMY TEAM':'STUDENT'?> · <?=$escape(date('M j, Y H:i',strtotime($reply['created_at'])))?></p><div><?=nl2br($escape($reply['message']))?></div></article><?php endforeach;?>
<?php if($user['role']!=='admin'||!empty($recipient)):?><form method="post" action="<?=$escape($baseUrl)?>/notifications/reply" class="admin-form notification-reply-form"><input type="hidden" name="_csrf" value="<?=$escape(Security::csrfToken())?>"><input type="hidden" name="notification_id" value="<?=(int)$notification['id']?>"><?php if($user['role']==='admin'):?><input type="hidden" name="recipient_student_id" value="<?=(int)$recipient['id']?>"><?php endif;?><label class="admin-label"><?=$user['role']==='admin'?'Reply privately to '.$escape($recipient['full_name']):'Private reply to the Academy'?><textarea class="admin-textarea" name="message" rows="4" maxlength="3000" required placeholder="Write your message..."></textarea></label><button class="button" type="submit">Send reply</button></form><?php endif;?></section></section>
